package com.southstand.football.matchdata;
import static org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest class T17CompleteMatchDataTests{@Autowired JdbcTemplate jdbc;
 @Test void everyGeneratedMatchHasCompleteFormationAndBench(){Integer bad=jdbc.queryForObject("SELECT COUNT(*) FROM(SELECT a.match_id,a.team_id,SUM(a.lineup_type='STARTER') starters,SUM(a.lineup_type IN('SUBSTITUTE','BENCH')) bench,SUM(a.lineup_type='STARTER' AND a.position='GOALKEEPER') sgk,SUM(a.lineup_type IN('SUBSTITUTE','BENCH') AND a.position='GOALKEEPER') bgk,SUM(a.lineup_type='STARTER' AND a.position='DEFENDER') df,SUM(a.lineup_type='STARTER' AND a.position='MIDFIELDER') mf,SUM(a.lineup_type='STARTER' AND a.position='FORWARD') fw FROM football_match_player_appearance a WHERE a.source='DEMO' AND a.is_deleted=0 GROUP BY a.match_id,a.team_id HAVING starters<>11 OR bench<5 OR sgk<>1 OR bgk<1 OR df<>4 OR mf<>3 OR fw<>3)x",Integer.class);assertThat(bad).isZero();}
 @Test void scoreAndTeamAggregatesAgree(){Integer bad=jdbc.queryForObject("SELECT COUNT(*) FROM football_match_team_stat t JOIN match_info m ON m.id=t.match_id JOIN(SELECT match_id,team_id,SUM(goals) goals,SUM(shots) shots,SUM(shots_on_target) sot,SUM(passes) passes,SUM(successful_passes) sp,SUM(yellow_cards) yc,SUM(red_cards) rc,SUM(saves) saves FROM football_match_player_stat WHERE is_deleted=0 GROUP BY match_id,team_id)p ON p.match_id=t.match_id AND p.team_id=t.team_id WHERE t.source='DEMO' AND t.is_deleted=0 AND(p.goals<>IF(t.team_id=m.home_team_id,m.home_score,m.away_score) OR t.shots<>p.shots OR t.shots_on_target<>p.sot OR t.passes<>p.passes OR t.successful_passes<>p.sp OR t.yellow_cards<>p.yc OR t.red_cards<>p.rc OR t.saves<>p.saves)",Integer.class);assertThat(bad).isZero();}}
